import json,pathlib
P=pathlib.Path('tmp/utterance-audit-2026-11-11');d=json.loads((P/'audit.json').read_text());items=json.loads((P/'items.json').read_text());
for r in d['items']:
 if r['number']<len(items):
  r['candidates']=[{k:f.get(k)for k in ['foodId','brandName','name','servings']}for f in items[r['number']].get('fatSecretResults',[])]
 else:r['candidates']=[]
 dct=r.get('estimate')or{}
 # Full candidate response snapshots remain available in raw local export; omit duplicate annotations here.
 dct.pop('candidateAnnotationsJson',None)
d['usage']=json.loads((P/'usage-window.json').read_text())[0]['results']
(P/'audit.json').write_text(json.dumps(d,ensure_ascii=False,indent=2))
replay=[dict(utterance=u['number'],transcript=u['input'],date=u['day'],historicalScore=u['score'],fixes=u['fixes'],expectations=[dict(food=r['name'],expected=r['expected'],failureStage=r['failureStage'],confidence=r['confidence'])for r in d['items']if r['number']in u['itemNumbers']])for u in d['utterances']if not u['boundary']and u['score']<2]
(P/'replay-cases.json').write_text(json.dumps(replay,ensure_ascii=False,indent=2))
head='''import {Stack,Row,Grid,H1,H2,H3,Text,Table,Stat,Link,Button,Select,TextInput,Checkbox,CollapsibleSection,Divider,useState,useHostTheme} from "cursor/canvas";
type Score = number|null;
type Stages = Record<string,Score>;
type Result = {amount?:string|null;calories?:number|null;protein?:number|null;servingType?:string|null;servingSize?:number|null;servingUnit?:string|null;servingMultiplier?:number|null;baseCalories?:number|null;baseProtein?:number|null};
type Item = {number:number;id:string;day:string;boundary:boolean;recovered:boolean;origin:string;route:string;input:string;name:string;status:string;error?:string|null;parser:Record<string,unknown>;search?:string|null;candidateCount:number;candidates:unknown[];selectedFood:Record<string,unknown>;selectedServing:Record<string,unknown>;library:Record<string,unknown>|null;estimate:Record<string,unknown>;result:Result;mathBasis:string;precisionRisk:{storedTotal:number;storedBase:number;multiplier:number;recalculated:number;delta:number}|null;observedReadyChanges:unknown[];stages:Stages;score:Score;failureStage:string;note:string;expected:string;fix:string;confidence:string};
type Utterance={number:number;day:string;boundary:boolean;input:string;score:number;label:string;stages:Stages;itemNumbers:number[];routes:string[];note:string;fixes:string[];confidence:string};
type Fix={id:string;priority:number;title:string;problem:string;change:string;existing:string;files:string[];validation:string;efficiency:string;confidence:string;utteranceNumbers:number[]};
type Audit={[key:string]:unknown;counts:Record<string,number>;rubric:Record<string,string>;utterances:Utterance[];items:Item[];fixes:Fix[];limitations:string[];sources:{title:string;url:string;note:string}[];usage:Record<string,unknown>[];modelConclusion:string;localValidation:{probes:unknown;targetedTests:string}};
'''
body='''
const stageText=(v:Score)=>v===null?"Unknown":v===2?"2 · Right":v===1?"1 · Close":"0 · Missed";
const localRoot="/Users/alexandersimone/All Code Projects/Code Projects/Checkmark Fitness/";
function Json({value}:{value:unknown}) {const theme=useHostTheme();return <pre style={{whiteSpace:"pre-wrap",wordBreak:"break-word",fontSize:12,lineHeight:1.5,padding:12,background:theme.fill.tertiary,color:theme.text.secondary,maxHeight:440,overflow:"auto"}}>{JSON.stringify(value,null,2)}</pre>}
function ItemDetail({r}:{r:Item}) {return <CollapsibleSection title={`${r.name} · ${r.route} · ${r.score===null?"No transcript score":stageText(r.score)}`} defaultOpen><Stack gap={10}>
 <Text weight="semibold">{r.failureStage} · {r.confidence} confidence{r.recovered?" · Recovered deleted record":""}</Text>
 <Text>{r.note}</Text><Text weight="semibold">What I would return: {r.expected}</Text>
 <Table headers={["Saved amount","Calories (kcal)","Protein (g)","State"]} rows={[[r.result.amount??"—",r.result.calories??"Unknown",r.result.protein??"Unknown",r.status??"Unrecorded"]]}/>
 {r.error&&<Text>{r.error}</Text>}
 {Object.keys(r.parser).length>0&&<CollapsibleSection title="1 · Parsed food, quantity, notes and search"><Json value={r.parser}/></CollapsibleSection>}
 <CollapsibleSection title={`2 · Search and selected product (${r.candidateCount} cached candidates)`}><Stack gap={8}><Text size="small">Saved search: {r.search??"Not retained"}. The actual HTTP query, cache-hit history and per-pass candidate mapping were not saved. Current library definitions can differ from the original.</Text><Text size="small">Route: {r.route}. Numeric basis: {r.mathBasis}.</Text><Json value={{selectedFood:r.selectedFood,selectedServing:r.selectedServing,library:r.library}}/>{r.candidates.length>0&&<CollapsibleSection title="All retained search candidates"><Json value={r.candidates}/></CollapsibleSection>}</Stack></CollapsibleSection>
 <CollapsibleSection title="3 · Relationship, model passes and serving result"><Json value={{estimate:r.estimate,result:r.result}}/></CollapsibleSection>
 {r.precisionRisk&&<Text>Stored-base risk: {r.precisionRisk.storedBase} kcal × {r.precisionRisk.multiplier} = {r.precisionRisk.recalculated} kcal, versus the saved {r.precisionRisk.storedTotal}. This is a recalculation risk, not evidence the original total was wrong.</Text>}
 {r.observedReadyChanges.length>0&&<CollapsibleSection title="Observed ready-to-ready changes (actor unknown)"><Json value={r.observedReadyChanges}/></CollapsibleSection>}
 {r.fix&&<Text size="small">Proposed repair: {r.fix}. See the repair plan below.</Text>}
 </Stack></CollapsibleSection>}
export default function AuditView(){const [query,setQuery]=useState("");const [verdict,setVerdict]=useState("all");const [fix,setFix]=useState("all");const [boundary,setBoundary]=useState(false);const [selected,setSelected]=useState(70);const [tab,setTab]=useState("utterances");const theme=useHostTheme();
 const matches=audit.utterances.filter(u=>(boundary||!u.boundary)&&(verdict==="all"||String(u.score)===verdict)&&(fix==="all"||u.fixes.includes(fix))&&`${u.day} ${u.input} ${u.routes.join(" ")}`.toLowerCase().includes(query.toLowerCase()));
 const active=audit.utterances.find(u=>u.number===selected)!;
 const other=audit.items.filter(r=>!r.boundary&&r.origin!=="Transcript");
 return <Stack gap={20} style={{padding:26,maxWidth:1450,margin:"0 auto"}}>
 <Stack gap={6}><Text size="small" tone="secondary">CHECKMARK FITNESS · ALEXANDER · READ-ONLY AUDIT</Text><H1>How your food utterances performed</H1><Text>October 13–November 11, 2026 · America/Los_Angeles · Scored from saved transcripts, parser/estimate snapshots, cached searches and recovery backups.</Text></Stack>
 <Grid columns="repeat(auto-fit,minmax(180px,1fr))" gap={16}><Stat label="Recoverable utterance groups" value="92"/><Stat label="Basically right · 2" value="46"/><Stat label="Close / uncertain · 1" value="27"/><Stat label="Missed the mark · 0" value="19"/></Grid>
 <Text>Half of the recoverable utterances were substantially what I would return. Another 27 were close or depended on unverified assumptions; 19 materially missed. Scores judge the full utterance, so one material failure can outweigh several correct foods. Small protein omissions remain “close” while their process defect is still flagged.</Text>
 <Text size="small" tone="secondary">Coverage: 180 current records, including 140 parser-backed foods across 91 exact-text/day groups; backups add one deleted utterance and the original failed Miso salad. One empty-audio capture is counted separately. This is all recoverable evidence, not proof that every attempted recording survived. Raw audio was not retained, so transcription accuracy is unknown.</Text>
 <Grid columns="repeat(auto-fit,minmax(270px,1fr))" gap={22}>
 <Stack gap={8}><H2>The first fixes should be process fixes</H2><Text>Correct product identity before quantity convenience. Keep calories/protein and their per-serving/total bases independent. Preserve full precision in serving math. Finish every parsed item.</Text><Text size="small">Stronger-model retries still chose unrelated sourdough and made unsupported portion assumptions. Keep the current default while fixing these failure paths.</Text></Stack>
 <Stack gap={8}><H2>Failures the diary now hides</H2><Text>Four Miso servings were parsed correctly but returned 170 kcal instead of 680. That record was deleted; a separate correct library log replaced it. “Honey brisket sandwich zuppa” became a generic sandwich plus Olive Garden soup, before another attempt became Honey Bacon Club.</Text></Stack>
 <Stack gap={8}><H2>A current math defect</H2><Text>A local probe gives 295 kcal for 180 g of the saved chicken reference, then stores 2 kcal/g. Recalculating that unchanged amount gives 360 kcal. This is rounding in app code, not a reason to buy a larger model.</Text><Text size="small">Other unresolved local probe: “70% of the whole thing” still returns no container fraction.</Text></Stack>
 </Grid>
 <CollapsibleSection title="Rubric, confidence and audit boundaries"><Stack gap={8}>{Object.entries(audit.rubric).map(([key,value])=><Text key={key} size="small"><strong>{key}:</strong> {value}</Text>)}{audit.limitations.map((value,i)=><Text key={i} size="small" tone="secondary">{value}</Text>)}</Stack></CollapsibleSection>
 <Divider/><H2>Inspect every utterance</H2>
 <Row gap={8} wrap><Button variant={tab==="utterances"?"primary":"secondary"} onClick={()=>setTab("utterances")}>Utterances</Button><Button variant={tab==="other"?"primary":"secondary"} onClick={()=>setTab("other")}>Scans, direct entries and capture failure</Button></Row>
 {tab==="utterances"?<Stack gap={12}>
 <Row gap={8} wrap><Select value={verdict} onChange={setVerdict} options={[{value:"all",label:"All scores"},{value:"0",label:"0 · Missed the mark"},{value:"1",label:"1 · Close / uncertain"},{value:"2",label:"2 · Basically right"}]}/><Select value={fix} onChange={setFix} options={[{value:"all",label:"All failure types"},...audit.fixes.map(f=>({value:f.id,label:`${f.id} · ${f.title}`}))]}/><TextInput value={query} onChange={setQuery} placeholder="Search exact words, food or date" style={{minWidth:250,flex:1}}/><Checkbox checked={boundary} onChange={setBoundary} label="Include Oct 12 appendix"/></Row>
 <Text size="small" tone="secondary">{matches.length} matching groups. Open an utterance for its split foods, queries, complete cached search results, selected source, raw model passes, serving basis and final return. Unknown stages are not counted as passes.</Text>
 {matches.length>0&&<Table headers={["Date","Score","Original transcript / details","Returned food records","Route"]} rows={matches.map(u=>[u.day+(u.boundary?" *":""),u.label,<Button variant="ghost" onClick={()=>setSelected(u.number)}>{u.input}</Button>,u.itemNumbers.length,u.routes.join(", ")])} columnAlign={["left","left","left","right","left"]} stickyHeader striped style={{maxHeight:500,overflow:"auto"}}/>}
 <Stack gap={12} style={{padding:18,background:theme.fill.tertiary}}><H3>{active.day} · Utterance {active.number} · {active.label}</H3><Text weight="semibold">“{active.input}”</Text><Text size="small">{active.confidence} confidence. Score is based on retained evidence; no original audio or immutable first-return event exists.</Text>{active.note&&<Text>{active.note}</Text>}<Table headers={["Stage","Assessment"]} rows={Object.entries(active.stages).map(([name,score])=>[name,stageText(score)])}/>{active.itemNumbers.map(n=><ItemDetail key={n} r={audit.items.find(r=>r.number===n)!}/>)}</Stack>
 </Stack>:<Stack gap={12}><Text size="small">These {other.length} records have no spoken-food transcript. Label-scan portions can still be audited; direct/barcode entries cannot be scored as utterances. The empty-audio failure has no transcription to judge.</Text>{other.map(r=><ItemDetail key={r.id} r={r}/>)}</Stack>}
 <Divider/><H2>Targeted repair plan</H2><Text>Proposals only. Some related changes already exist locally; passing their tests does not prove live behavior is fixed. No code or food records were changed by this audit.</Text>
 {audit.fixes.map(f=><CollapsibleSection key={f.id} title={`${f.id} · Priority ${f.priority} · ${f.title}`} defaultOpen={f.id==="F1"||f.id==="F3"||f.id==="F5"}><Stack gap={10}><Text><strong>Observed:</strong> {f.problem}</Text><Text><strong>Change:</strong> {f.change}</Text><Text><strong>Reuse:</strong> {f.existing}</Text><Text><strong>Validation:</strong> {f.validation}</Text><Text><strong>Efficiency:</strong> {f.efficiency}</Text><Text size="small" tone="secondary">{f.confidence} Linked to {f.utteranceNumbers.length} scored utterance groups; scan/direct issues are separate. Counts overlap.</Text><Row gap={8} wrap>{f.files.map(path=><Link key={path} href={localRoot+path}>{path.split("/").pop()}</Link>)}</Row></Stack></CollapsibleSection>)}
 <H2>Model and efficiency decision</H2><Text>{audit.modelConclusion}</Text>
 <Text size="small">Reuse first: the app already has replay scripts, serving audits, deterministic conversions, personal vocabulary and usage metadata. Extending these is less integration effort and keeps food transcripts local to the existing audit workflow. A new tracing/evaluation platform is unnecessary for this audit; no new dependency was added.</Text>
 <CollapsibleSection title="Observed calls, tokens and latency"><Stack gap={8}><Text size="small">Source: production ai_request_usage, Alexander, app-tagged calls, October 13–November 11 local; first retained telemetry is October 17. Counts are upstream AI calls, not utterances or end-to-end latency. Calls cannot be reliably joined to saved food IDs. Cross-checks and retries share feature labels.</Text><Table headers={["Feature","Model","AI calls","Input tokens","Output tokens","Mean upstream latency (ms)"]} rows={audit.usage.map(r=>[String(r.feature),String(r.model),String(r.calls),String(r.input_tokens),String(r.output_tokens),Math.round(Number(r.avg_ms))])}/><Text size="small">Do not divide these by 92 to claim per-utterance cost: unsaved attempts, retries and refreshes are included and telemetry coverage may be partial.</Text></Stack></CollapsibleSection>
 <CollapsibleSection title="Local reproducibility evidence"><Text size="small">{audit.localValidation.targetedTests} Probes call current functions offline; they do not replay the model or prove fixes improve future responses.</Text><Json value={audit.localValidation.probes}/></CollapsibleSection>
 <CollapsibleSection title="Source evidence"><Stack gap={10}>{audit.sources.map(s=><Stack gap={3} key={s.title}>{s.url?<Link href={s.url}>{s.title}</Link>:<Text weight="semibold">{s.title}</Text>}<Text size="small" tone="secondary">{s.note}</Text></Stack>)}</Stack></CollapsibleSection>
 <Row gap={14} wrap><Link href={localRoot+"tmp/utterance-audit-2026-11-11/utterance-scores.csv"}>All utterance scores · CSV</Link><Link href={localRoot+"tmp/utterance-audit-2026-11-11/audit.json"}>Full audit evidence · JSON</Link><Link href={localRoot+"tmp/utterance-audit-2026-11-11/replay-cases.json"}>Exact-word repair validation cases · JSON</Link></Row>
 </Stack>
}
'''
(P/'audit.canvas.draft').write_text(head+'const audit: Audit = '+json.dumps(d,ensure_ascii=False,separators=(',',':'))+';\n'+body)
print('canvas',len((P/'audit.canvas.draft').read_bytes()),'bytes; close/failure replay cases',len(replay))
